package com.company.skillplatform.bundle.infrastructure;
import com.company.skillplatform.bundle.application.BundleService;import com.company.skillplatform.bundle.infrastructure.entity.SkillBundleEntity;import com.company.skillplatform.bundle.infrastructure.repository.SkillBundleRepository;import java.time.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class BundleBuildWorker{private final SkillBundleRepository bundles;private final BundleService builder;private final Clock clock;private final Duration lease;private final int maxRetries;public BundleBuildWorker(SkillBundleRepository b,BundleService builder,@Value("${skill.bundle.build-lease:PT15M}")Duration lease,@Value("${skill.bundle.max-retries:3}")int maxRetries){bundles=b;this.builder=builder;this.lease=lease;this.maxRetries=maxRetries;clock=Clock.systemUTC();}@Scheduled(fixedDelayString="${skill.bundle.worker-delay-ms:30000}")@Transactional public void process(){Instant cutoff=clock.instant().minus(lease);for(SkillBundleEntity b:bundles.findByStatus("BUILDING"))if(b.getTimeCreated()!=null&&b.getTimeCreated().isBefore(cutoff)){b.failed("BUILD_LEASE_EXPIRED","Bundle build lease expired");bundles.save(b);}for(SkillBundleEntity b:bundles.findByStatusAndRetryCountLessThan("FAILED",maxRetries))builder.retryBuild(b.getId());}}
